/* @layer shared-asset-extraction @kind logic */
import { dec, hexN } from './shared/py-format';
import type { Sprite } from './shared/oam-decode';

const NTILE = 0x40;

interface SettleKf {
  name: string;
  n: number;
  pal: number;
  objOff: number;
  nObj: number;
  ax: number;
  ay: number;
  tiles: Uint8Array[];
}

const HEAD = [
  '// AUTO-GENERATED by tools/gen/battle_settle.py -- DO NOT EDIT.',
  '// CT victory SETTLE-IN ladder: the ~72f animated celebration that plays INTO the held',
  '// victory pose (battle_end.h kf0/kf1). Dossier: battle_gato_idle_victory.md section C.',
  '// GATO fight, Crono seat0 (pal5) + Marle seat1 (pal6). Each keyframe = OAM assembly +',
  '// its OWN OBJ tiles (poses STREAM tile content). Endpoints: C0/M0 = idle-at-kill; the',
  '// FINAL pose C5/M5 == battle_end.h kf0/kf1 (reused by the render, not re-baked here).',
  '// A pose OBJ pixel at OAM (x,y) lands at oracle fb true-pixel (x, y+8) (verified).',
  '#ifndef CT_BATTLE_SETTLE_H\n#define CT_BATTLE_SETTLE_H\n#include <stdint.h>\n',
  '// Flat OBJ list across all keyframes (OAM-index order; composite HIGH oidx first).',
  'typedef struct { uint8_t oidx; int16_t x; uint8_t y; uint16_t tile;',
  '                 uint8_t pal, prio, hf, vf; } CtSettleObj;',
];

const KF_HEAD = [
  '// Keyframe table. pc: 0=Crono(pal5) / 1=Marle(pal6). objOff/nObj = slice of the flat OBJ',
  '// list; tileKf = index into ctBattleSettleTiles; anchorX/Y = OAM min-corner; repN = source',
  '// peek frame (kill ~N170). The RENDER schedule (victoryHold windows) is below.',
  'typedef struct { const char* name; uint8_t pc, pal, objOff, nObj, tileKf;',
  '                 int16_t anchorX; uint8_t anchorY; uint16_t repN; } CtSettleKeyframe;',
];

const SCHED_HEAD = [
  '// --- RENDER SCHEDULE (battle_gato_idle_victory.md C.2): victoryHold (real frames since the',
  '// win) -> ladder keyframe. Per PC, pick the LATEST keyframe whose startV <= victoryHold; at/after',
  '// endV land on the HELD battle_end.h kf0(Crono)/kf1(Marle). victoryHold maps to the dossier peek',
  '// dwell windows (kill ~N170 -> startV = repN-170-ish, snapped to the C.2 window onsets). A dead PC',
  '// does NOT celebrate (the caller keeps the fallen path). kfIdx = index into ctBattleSettleKf.',
  'typedef struct { uint8_t startV, kfIdx; } CtSettleStep;',
];

const SCHED: Record<string, number> = { C0: 1, C1: 20, C2: 32, C3: 40, C4: 52, M0: 1, M1: 12, M2: 24, M3: 32, M4: 52 };

const objLine = (s: Sprite): string =>
  `  { ${dec(s.idx, 3)}, ${dec(s.x, 4)}, ${dec(s.y, 3)}, 0x${hexN(s.tile, 3)}, ${s.pal}, ${s.prio}, ${s.hflip}, ${s.vflip} },`;

const stepLines = (kfs: SettleKf[], pc: number, tag: string): string[] => {
  const want = pc === 0 ? 5 : 6;
  const steps = kfs
    .map((kf, i): [number, number] => [SCHED[kf.name] as number, i])
    .filter(([, i]) => (kfs[i] as SettleKf).pal === want)
    .sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const cap = tag.charAt(0) + tag.slice(1).toLowerCase();
  return [
    `#define CT_SETTLE_${tag}_NSTEP ${steps.length}`,
    `static const CtSettleStep ctBattleSettle${cap}[CT_SETTLE_${tag}_NSTEP] = {`,
    ...steps.map(([sv, ki]) => `  { ${sv}, ${ki} },`),
    '};',
  ];
};

/** The text of battle_settle.h (emit). */
const emitSettle = (kfs: SettleKf[], objFlat: Sprite[]): string => {
  const kfLines = kfs.map((kf, i) => {
    const pc = kf.pal === 5 ? 0 : 1;
    return `  { "${kf.name}", ${pc}, ${kf.pal}, ${kf.objOff}, ${kf.nObj}, ${i}, ${dec(kf.ax, 4)}, ${dec(kf.ay, 3)}, ${kf.n} },`;
  });
  const tileLines = kfs.flatMap((kf, i) => [
    `  { // kf${i} ${kf.name} (N${kf.n} pal${kf.pal})`,
    ...kf.tiles.map((t) => `    {${Array.from(t, (b) => `0x${hexN(b, 2)}`).join(',')}},`),
    '  },',
  ]);
  const lines = [
    ...HEAD,
    `#define CT_SETTLE_NOBJ ${objFlat.length}`,
    'static const CtSettleObj ctBattleSettleObj[CT_SETTLE_NOBJ] = {',
    ...objFlat.map(objLine),
    '};\n',
    ...KF_HEAD,
    `#define CT_SETTLE_NKF ${kfs.length}`,
    'static const CtSettleKeyframe ctBattleSettleKf[CT_SETTLE_NKF] = {',
    ...kfLines,
    '};\n',
    `// Per-keyframe OBJ 8x8 tiles 0x00..0x${hexN(NTILE - 1, 2)} (4bpp planar, 32 B) -- streamed per pose.`,
    '// 16x16 sprite of tile T uses 8x8 tiles T, T+1, T+0x10, T+0x11.',
    `#define CT_SETTLE_NTILE 0x${hexN(NTILE, 2)}`,
    'static const uint8_t ctBattleSettleTiles[CT_SETTLE_NKF][CT_SETTLE_NTILE][32] = {',
    ...tileLines,
    '};\n',
    ...SCHED_HEAD,
    ...stepLines(kfs, 0, 'CRONO'),
    ...stepLines(kfs, 1, 'MARLE'),
    '#define CT_SETTLE_CRONO_ENDV 64   // >= this victoryHold -> held battle_end kf0',
    '#define CT_SETTLE_MARLE_ENDV 68   // >= this victoryHold -> held battle_end kf1',
    '#endif // CT_BATTLE_SETTLE_H',
  ];
  return `${lines.join('\n')}\n`;
};

export type { SettleKf };
export { emitSettle, NTILE };
